#include <iostream>
#include <vector>
using namespace std;

int main() {
    int count;
    cin >> count;

    vector<string> studentNames(count);
    vector<int> studentGrades(count);

    for (int i = 0; i < count; i++) {
        cin >> studentNames[i];
        cin >> studentGrades[i];
    }

    for (int i = 0; i < count; i++) {
        cout << studentNames[i] << " -> " << studentGrades[i] << "\n";
    }
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int sum = 0;

    for (int i = 0; i < n; i++) {
        int grade;
        cin >> grade;
        sum += grade;
    }

    cout << sum / (double)n << endl;
    return 0;
}
